// Own: zzOWN.com - Own Fast. Work Faster.  | Ema: zzown.com@gmail.com
// Des: Owner tools: support report, backup, export, purge old logs
// Flo: report = redacted folder (version, safe config, last log, alerts) > backup = copy the state db > export = ledger + log as JSONL > purge = drop rows older than msgs_keep_days
// I/O: Ctx (state + folder) > files in <stat>/report, backup, export; printed paths and counts; never includes cookies, profile data or private text
// ===================================================================
const std = @import("std"); const atom = @import("ut-file-atom.zig"); const builtin = @import("builtin"); const task = @import("ru-task-runn.zig"); const priv = @import("ru-safe-priv.zig");
pub const VERS = "0.3.0";
const CF = .{ .dbfi = "fb-state.db", .nlog = 50, .nala = 20, .maxz = 1 << 20 };
const Safe = struct { base_urlz_main: []const u8, capz_post_dayz: u32, capz_comm_dayz: u32, capz_mark_dayz: u32, capz_grou_dayz: u32, capz_frie_dayz: u32, capz_dmsg_dayz: u32, capz_reac_dayz: u32, capz_shar_dayz: u32, capz_admn_dayz: u32, capz_evnt_dayz: u32, capz_stor_dayz: u32, capz_prof_dayz: u32, quie_hour_rang: [2]u8, quie_zone_minu: i32, warm_dayz_coun: u32, retr_coun_maxz: u32, smar_mode_enab: bool, lang_main_code: []const u8, brow_vers_minz: u32, msgs_keep_days: u32, wait_maxx_minu: u32, noti_chai_orde: []const []const u8 };
fn put(ctx: *task.Ctx, dir: []const u8, name: []const u8, data: []const u8) !void { const path = try std.fs.path.join(ctx.aren, &.{ dir, name }); try atom.put(ctx.aren, ctx.iozz, path, data); }
pub fn report(ctx: *task.Ctx) ![]const u8 { const dir = try std.fs.path.join(ctx.aren, &.{ ctx.statd, "report" }); try std.Io.Dir.cwd().createDirPath(ctx.iozz, dir); const cf = ctx.conf; const info = try std.fmt.allocPrint(ctx.aren, "fb-face-webs {s}\nos {s}\ncpu {s}\n", .{ VERS, @tagName(builtin.os.tag), @tagName(builtin.cpu.arch) }); try put(ctx, dir, "info.txt", info); const safe: Safe = .{ .base_urlz_main = cf.base_urlz_main, .capz_post_dayz = cf.capz_post_dayz, .capz_comm_dayz = cf.capz_comm_dayz, .capz_mark_dayz = cf.capz_mark_dayz, .capz_grou_dayz = cf.capz_grou_dayz, .capz_frie_dayz = cf.capz_frie_dayz, .capz_dmsg_dayz = cf.capz_dmsg_dayz, .capz_reac_dayz = cf.capz_reac_dayz, .capz_shar_dayz = cf.capz_shar_dayz, .capz_admn_dayz = cf.capz_admn_dayz, .capz_evnt_dayz = cf.capz_evnt_dayz, .capz_stor_dayz = cf.capz_stor_dayz, .capz_prof_dayz = cf.capz_prof_dayz, .quie_hour_rang = cf.quie_hour_rang, .quie_zone_minu = cf.quie_zone_minu, .warm_dayz_coun = cf.warm_dayz_coun, .retr_coun_maxz = cf.retr_coun_maxz, .smar_mode_enab = cf.smar_mode_enab, .lang_main_code = cf.lang_main_code, .brow_vers_minz = cf.brow_vers_minz, .msgs_keep_days = cf.msgs_keep_days, .wait_maxx_minu = cf.wait_maxx_minu, .noti_chai_orde = cf.noti_chai_orde }; try put(ctx, dir, "conf.json", try std.json.Stringify.valueAlloc(ctx.aren, safe, .{})); const rows = try ctx.store.logRecent(ctx.aren, CF.nlog); var lg: std.ArrayList(u8) = .empty; for (rows) |row| try lg.print(ctx.aren, "{d} {s} {s} {s}\n", .{ row.ts, if (row.ok) "ok" else "FAIL", row.kind, row.what }); try put(ctx, dir, "log.txt", lg.items); const apath = try std.fs.path.join(ctx.aren, &.{ ctx.statd, "alerts.txt" }); const atxt = std.Io.Dir.cwd().readFileAlloc(ctx.iozz, apath, ctx.aren, .limited(CF.maxz)) catch ""; var lines = std.mem.splitScalar(u8, atxt, '\n'); var keep: std.ArrayList([]const u8) = .empty; while (lines.next()) |ln| { if (ln.len > 0) try keep.append(ctx.aren, ln); } const from = if (keep.items.len > CF.nala) keep.items.len - CF.nala else 0; var al: std.ArrayList(u8) = .empty; for (keep.items[from..]) |ln| try al.print(ctx.aren, "{s}\n", .{ln}); try put(ctx, dir, "alerts.txt", al.items); task.say(ctx, "report saved: {s} (send this folder for support; it holds no cookies and no private text)", .{dir}); return dir; }
pub fn backup(ctx: *task.Ctx) ![]const u8 { try ctx.store.db.exec("PRAGMA wal_checkpoint(TRUNCATE);"); const dir = try std.fs.path.join(ctx.aren, &.{ ctx.statd, "backup" }); try std.Io.Dir.cwd().createDirPath(ctx.iozz, dir); const src = try std.fs.path.join(ctx.aren, &.{ ctx.statd, CF.dbfi }); const name = try std.fmt.allocPrint(ctx.aren, "fb-state-{d}.db", .{task.nowMs(ctx)}); const dst = try std.fs.path.join(ctx.aren, &.{ dir, name }); try std.Io.Dir.cwd().copyFile(src, std.Io.Dir.cwd(), dst, ctx.iozz, .{}); task.say(ctx, "backup saved: {s}", .{dst}); return dst; }
pub fn exportData(ctx: *task.Ctx) !u32 { const dir = try std.fs.path.join(ctx.aren, &.{ ctx.statd, "export" }); try std.Io.Dir.cwd().createDirPath(ctx.iozz, dir); const led = try ctx.store.ledgList(ctx.aren); var lj: std.ArrayList(u8) = .empty; for (led) |row| { try lj.appendSlice(ctx.aren, try std.json.Stringify.valueAlloc(ctx.aren, row, .{})); try lj.append(ctx.aren, '\n'); } try put(ctx, dir, "ledger.jsonl", lj.items); const logs = try ctx.store.logRecent(ctx.aren, 100000); var gj: std.ArrayList(u8) = .empty; for (logs) |row| { try gj.appendSlice(ctx.aren, try std.json.Stringify.valueAlloc(ctx.aren, row, .{})); try gj.append(ctx.aren, '\n'); } try put(ctx, dir, "log.jsonl", gj.items); task.say(ctx, "exported {d} ledger rows and {d} log rows to {s}", .{ led.len, logs.len, dir }); return @intCast(led.len + logs.len); }
pub fn purgeRun(ctx: *task.Ctx) !i64 { const cnt = try priv.purge(ctx); task.say(ctx, "purged {d} old rows (older than {d} days)", .{ cnt, ctx.conf.msgs_keep_days }); return cnt; }
